-- Install Marvel/hero costumes generated by costume-tools/build_marvel_costumes.py
SET NAMES utf8mb4;
START TRANSACTION;

DELETE FROM item_shop_option WHERE item_shop_id IN (SELECT id FROM item_shop WHERE tab_id = 1120 AND temp_id IN (2077, 2078, 2079, 2080, 2081, 2082));
DELETE FROM item_shop WHERE tab_id = 1120 AND temp_id IN (2077, 2078, 2079, 2080, 2081, 2082);
